const input = $input.first().json;
const workflowId = input.workflowId || 'unknown';
const workflowName = input.workflowName || 'Unknown Workflow';
const executionId = input.executionId || null;
const status = input.status || 'success';
const flow = input.flow || 'main';
const metadata = input.metadata || {};
const durationMs = input.durationMs || 0;

return [{ json: { workflowId, workflowName, executionId, status, flow, metadata, durationMs, timestamp: new Date().toISOString() } }];

const input = $input.first().json;
const postgres = Postgres.main;

try {
  await postgres.query(`INSERT INTO workflows.workflow_executions (workflow_id, workflow_name, execution_id, status, started_at, finished_at, duration_ms, metadata) VALUES ($1, $2, $3, $4, $5, $5, $6, $7::jsonb)`, [input.workflowId, input.workflowName, input.executionId, input.status, new Date().toISOString(), input.durationMs, JSON.stringify({ flow: input.flow, ...input.metadata })]);
} catch (e) {}

return [{ json: input }];

const input = $input.first().json;
if (input.status !== 'error') return [{ json: input }];

const postgres = Postgres.main;
try {
  await postgres.query(`INSERT INTO workflows.workflow_errors (workflow_id, workflow_name, execution_id, error_type, message, severity, created_at) VALUES ($1, $2, $3, $4, $5, $6, CURRENT_TIMESTAMP)`, [input.workflowId, input.workflowName, input.executionId, input.metadata?.errorType || 'workflow_error', input.metadata?.errorMessage || 'Execution failed', input.metadata?.severity || 'medium']);
} catch (e) {}

return [{ json: input }];
